// All 4 SearXNG nodes ran sequentially upstream, so their outputs
// are all available by name in the execution context.
const allResults = [
  ...($('SearXNG Query 1 — High-Comp Eng Hire').item.json.results || []),
  ...($('SearXNG Query 2 — Recent Raise').item.json.results || []),
  ...($('SearXNG Query 3 — Explicit Problem Signal').item.json.results || []),
  ...($('SearXNG Query 4 — Premature ML Hire').item.json.results || [])
];

// Deduplicate by domain, keeping first occurrence.
const seen = new Set();
const unique = [];

for (const r of allResults) {
  if (!r.url) continue;
  let domain;
  try {
    domain = new URL(r.url).hostname.replace(/^www\./, '');
  } catch (e) {
    continue;
  }
  if (seen.has(domain)) continue;
  seen.add(domain);

  unique.push({
    company: r.title
      ? r.title.split('|')[0].split(' - ')[0].split(' – ')[0].trim()
      : domain,
    url: r.url,
    domain,
    title: r.title || '',
    snippet: (r.content || '').replace(/\s+/g, ' ').trim().substring(0, 300)
  });

  if (unique.length >= 20) break;
}

return [{ json: { prospects: unique } }];

