// Parse the LLM's JSON array output. Strip code fences if present.
const raw = $input.first().json.message.content;
const cleaned = raw
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/i, '')
  .trim();

let scored;
try {
  scored = JSON.parse(cleaned);
} catch (err) {
  return [{ json: {
    parseError: err.message,
    rawOutput: raw,
    scored: []
  }}];
}

return [{ json: { scored } }];

// Filter to score >= 4, sort desc, take top 5.
const scored = $input.first().json.scored || [];

const topLeads = scored
  .filter(function(p) { return p.score >= 4; })
  .sort(function(a, b) { return b.score - a.score; })
  .slice(0, 5);

return [{ json: { topLeads } }];

// Build the Postgres upsert SQL from topLeads.
// Doing this in a Code node avoids template-expression-in-SQL weirdness.
const topLeads = $input.first().json.topLeads || [];

if (topLeads.length === 0) {
  // Pass through with empty sql so Postgres node is a no-op
  return [{ json: { sql: 'SELECT 1', topLeads } }];
}

// Escape single quotes for SQL safety
function esc(v) {
  return String(v || '').replace(/'/g, "''");
}

const rows = topLeads.map(function(l) {
  return (
    `('${esc(l.domain)}', '${esc(l.company)}', '${esc(l.url)}',` +
    ` '${esc(l.icpCategory)}', ${parseInt(l.score, 10) || 0},` +
    ` '${esc(JSON.stringify(l.signals || []))}'::jsonb,` +
    ` 'new', 'daily-hunter')`
  );
});

const sql = [
  'INSERT INTO leads (domain, company, url, icp_bucket, score, signals, status, source)',
  'VALUES',
  rows.join(',\n'),
  'ON CONFLICT (domain) DO UPDATE SET',
  '  score        = EXCLUDED.score,',
  '  icp_bucket   = EXCLUDED.icp_bucket,',
  '  signals      = EXCLUDED.signals,',
  '  last_touched = now()',
  "WHERE leads.status = 'new'"
].join('\n');

return [{ json: { sql, topLeads } }];

// topLeads carried forward from Prepare Upsert SQL — Postgres output replaces
// $json, so we pull from the named node upstream.
const topLeads = $('Prepare Upsert SQL').item.json.topLeads || [];

if (topLeads.length === 0) {
  return [{ json: {
    slackText: "🕵️ *Bugsy's Morning Sweep — nothin' clocked in today, boss.* Searches ran clean but nothin' hit the bar. I'll be back at it tomorrow mornin'."
  }}];
}

const lines = topLeads.map(function(lead) {
  const signalStr = (lead.signals || []).slice(0, 3).join(' · ');
  return [
    `🔥 *[Score: ${lead.score}/10]* ${lead.company} — ${lead.url}`,
    `ICP: ${lead.icpCategory} — ${lead.reason}`,
    `📌 Signals: ${signalStr}`,
    `→ /research ${lead.url} to go deep`
  ].join('\n');
});

const date = new Date().toLocaleDateString('en-US', {
  weekday: 'long', month: 'short', day: 'numeric'
});
const header = `*🗂 Bugsy's Morning Sweep — ${date}*\nListen up, boss. I ran the boards this mornin' and here's what I clocked. Top ${topLeads.length} prospects worth your attention:`;

return [{ json: { slackText: [header, '', ...lines].join('\n\n') } }];
